<script setup lang="ts">
import type { Announcement, Period, User } from '~/domain/types'
import { formatDemoTime, roleLabel } from '~/domain/selectors'
definePageMeta({ layout: 'workspace' })
useHead({ title: 'Pengelolaan - UKIN PPG UNJ' })
const u = useUkin(), { error, message, act } = useOperationFeedback(), tab = ref('Periode')
const data = computed(() => u.user.value?.role === 'pengelola' ? u.operations.getManagement() : null)
const reason = ref(''), periodForm = ref<Period | null>(null), periodRevision = ref<number | null>(null)
const dates = reactive({ collectionOpensAt: '', collectionClosesAt: '', assessmentOpensAt: '', assessmentClosesAt: '' }), subjects = ref('')
const dateLabels = { collectionOpensAt: 'Pengumpulan dibuka', collectionClosesAt: 'Pengumpulan ditutup', assessmentOpensAt: 'Penilaian dibuka', assessmentClosesAt: 'Penilaian ditutup' }
const windowPeriod = ref(''), windowStart = ref(''), windowEnd = ref('')
function editPeriod(p?: Period, duplicate = false) {
  const template = p ?? data.value?.periods[0]; if (!template) return
  periodForm.value = JSON.parse(JSON.stringify(template)); periodForm.value!.track ??= 'PPG'
  periodForm.value!.subjects ??= [...new Set(data.value!.attempts.filter(a => a.periodId === template.id).map(a => a.subject))]
  periodRevision.value = p && !duplicate ? p.revision ?? 0 : null
  if (!p || duplicate) { periodForm.value!.id = ''; periodForm.value!.name = `${template.name} - Salinan`; periodForm.value!.archived = false; delete periodForm.value!.moderationWindow }
  subjects.value = periodForm.value!.subjects.join(', ')
  for (const key of Object.keys(dates) as (keyof typeof dates)[]) dates[key] = wibInput(periodForm.value![key])
  reason.value = ''
}
function savePeriod() { act(() => { const p = periodForm.value!; const normalized = { ...p, subjects: subjects.value.split(',').map(s => s.trim()).filter(Boolean) }; for (const k of Object.keys(dates) as (keyof typeof dates)[]) normalized[k] = fromWib(dates[k]); u.operations.savePeriod(normalized, periodRevision.value, reason.value); periodForm.value = null }, 'Periode tersimpan. Aturan yang sudah dipakai tetap dilindungi.') }
const account = ref<Pick<User, 'id' | 'displayName' | 'email' | 'role' | 'examinerKind' | 'active'> | null>(null)
function editUser(user?: User) { account.value = user ? { id: user.id, displayName: user.displayName, email: user.email, role: user.role, examinerKind: user.examinerKind, active: user.active } : { id: '', displayName: '', email: '', role: 'peserta', active: true }; reason.value = '' }
function saveUser() { act(() => { const value = { ...account.value! }; if (value.role !== 'penguji') delete value.examinerKind; u.operations.saveManagedUser(value, reason.value); account.value = null }, 'Akun fiktif disimpan. Hanya empat akun demo bawaan yang dapat dipakai masuk.') }
const attemptId = ref(''), dosen = ref(''), guru = ref(''), assignmentToken = ref(''), assignmentPreview = ref<ReturnType<typeof u.operations.previewAssignment> | null>(null), confirmPair = ref(false)
watch(attemptId, () => { const preview = act(() => u.operations.previewAssignment(attemptId.value), 'Paket dan penugasan dimuat.'); if (preview) { assignmentPreview.value = preview; assignmentToken.value = preview.token; dosen.value = preview.assignments.find(a => a.kind === 'dosen')?.examinerId ?? ''; guru.value = preview.assignments.find(a => a.kind === 'guru')?.examinerId ?? ''; confirmPair.value = false; reason.value = '' } })
function savePair() { act(() => { u.operations.assignPair(attemptId.value, dosen.value, guru.value, assignmentToken.value, reason.value, confirmPair.value); assignmentPreview.value = u.operations.previewAssignment(attemptId.value); assignmentToken.value = assignmentPreview.value.token; confirmPair.value = false }, 'Pasangan tersimpan. Penilaian milik penguji yang diganti tetap ada dalam riwayatnya.') }
const enrollment = reactive({ periodId: '', participantId: '', subject: '' })
const announcement = ref<Pick<Announcement, 'id' | 'title' | 'body' | 'audience' | 'periodIds'> | null>(null), announcementRevision = ref<number | null>(null)
function editAnnouncement(a?: Announcement) { announcement.value = a ? JSON.parse(JSON.stringify(a)) : { id: '', title: '', body: '', audience: ['peserta'], periodIds: [] }; announcementRevision.value = a?.revision ?? null }
function saveAnnouncement() { act(() => { u.operations.saveAnnouncement(announcement.value!, announcementRevision.value); announcement.value = null }, 'Draf pengumuman tersimpan. Terbitkan setelah meninjau isi dan penerimanya.') }
</script>
<template>
  <div v-if="data" class="operations-page"><header><p class="eyebrow">PENGELOLA / ADMINISTRASI DEMO</p><h1>Siapkan alur, jaga jejaknya.</h1><p class="muted">Perubahan berlaku pada data fiktif di browser ini. Akun tambahan tidak mengirim undangan atau menyediakan autentikasi nyata.</p></header>
    <nav class="op-tabs" aria-label="Pengelolaan"><button v-for="t in ['Periode', 'Akun', 'Penugasan', 'Pengumuman', 'Aktivitas']" :key="t" :aria-pressed="tab === t" @click="tab = t">{{ t }}</button></nav>
    <p v-if="error" class="op-error" role="alert">{{ error }}</p><p v-if="message" class="op-success" role="status">{{ message }}</p>
    <label v-if="tab !== 'Aktivitas'" class="op-field">Alasan tindakan administratif<textarea v-model="reason" maxlength="5000" rows="2" placeholder="Jelaskan tujuan perubahan, pengarsipan, atau penetapan." /><small>Dicatat bersama aktor dan waktu DemoClock. Draf pengumuman memakai judul sebagai catatan simpan.</small></label>
    <template v-if="tab === 'Periode'"><section class="op-hero"><div><h2>Periode &amp; aturan demo</h2><p class="op-caption">Aturan penilaian terkunci setelah pekerjaan dimulai. Gunakan duplikasi untuk aturan baru. Jendela moderasi terpisah dapat dibuka dengan alasan.</p></div><UButton @click="editPeriod()">Periode baru</UButton></section>
      <article v-for="p in data.periods" :key="p.id" class="op-panel"><div class="op-row"><div><h2>{{ p.name }}</h2><p class="op-caption">{{ p.year }} / {{ p.track ?? 'PPG' }} / {{ p.rubricVersionId }}</p></div><span class="op-tag">{{ p.archived ? 'Diarsipkan' : 'Aktif' }}</span></div><div class="op-grid"><p class="op-caption">Pengumpulan<br />{{ formatDemoTime(p.collectionOpensAt) }}<br />sampai {{ formatDemoTime(p.collectionClosesAt) }}</p><p class="op-caption">Penilaian<br />{{ formatDemoTime(p.assessmentOpensAt) }}<br />sampai {{ formatDemoTime(p.assessmentClosesAt) }}</p></div><p class="op-caption">Wawancara: {{ p.interviewEnabled ? p.interviewRequiredForRelease ? 'Aktif, wajib untuk publikasi' : 'Aktif, opsional untuk publikasi' : 'Nonaktif' }} / Kuota final per penguji per hari WIB: {{ p.quota ?? 'Tanpa batas demo' }}</p><p v-if="p.moderationWindow" class="op-warning">Jendela moderasi: {{ formatDemoTime(p.moderationWindow.opensAt) }} - {{ formatDemoTime(p.moderationWindow.closesAt) }}. {{ p.moderationWindow.reason }}</p><div class="op-actions"><UButton variant="soft" @click="editPeriod(p)">Sunting</UButton><UButton variant="outline" @click="editPeriod(p, true)">Duplikasi aturan</UButton><UButton v-if="!p.archived" color="neutral" variant="outline" @click="act(() => u.operations.archivePeriod(p.id, reason))">Arsipkan</UButton><UButton v-if="!data.attempts.some(a => a.periodId === p.id)" color="error" variant="ghost" @click="act(() => u.operations.deletePeriod(p.id, reason))">Hapus periode kosong</UButton></div></article>
      <form v-if="periodForm" class="op-panel" @submit.prevent="savePeriod"><h2>{{ periodRevision === null ? 'Periode baru dari aturan salinan' : 'Sunting periode' }}</h2><div class="op-grid"><label class="op-field">Nama periode<input v-model="periodForm.name" required maxlength="160" /></label><label class="op-field">Jenis PPG<input v-model="periodForm.track" required /></label><label class="op-field">Tahun<input v-model.number="periodForm.year" type="number" min="2000" max="2100" required /></label><label class="op-field">Bidang studi (pisahkan koma)<input v-model="subjects" required /></label><label v-for="(label, key) in dateLabels" :key="key" class="op-field">{{ label }} (WIB)<input v-model="dates[key]" type="datetime-local" required /></label><label class="op-field">Rubrik demo<select v-model="periodForm.rubricVersionId"><option value="demo-12-v1">Demo 12 indikator / versi 1.0</option></select></label><label class="op-field">Sumber studi kasus<select v-model="periodForm.caseStudySource"><option value="participant_report">Laporan peserta</option><option value="exam_snapshot">Snapshot ujian fiktif</option></select></label></div><label class="op-check"><input v-model="periodForm.requirements.fullVideo" type="checkbox" />Wajib video utuh</label><label class="op-check"><input v-model="periodForm.requirements.summaryVideo" type="checkbox" />Wajib video ringkasan</label><label class="op-check"><input v-model="periodForm.interviewEnabled" type="checkbox" />Aktifkan wawancara kondisional</label><label class="op-check"><input v-model="periodForm.interviewRequiredForRelease" type="checkbox" />Wawancara wajib selesai sebelum publikasi</label><label class="op-field">Kuota final awal per penguji per hari WIB (kosong = nonaktif)<input :value="periodForm.quota ?? ''" type="number" min="1" @input="periodForm.quota = ($event.target as HTMLInputElement).value ? Number(($event.target as HTMLInputElement).value) : null" /></label><div class="op-actions"><UButton type="submit">Simpan periode</UButton><UButton color="neutral" variant="outline" @click="periodForm = null">Batal</UButton></div></form>
      <form class="op-panel" @submit.prevent="act(() => u.operations.setModerationWindow(windowPeriod, fromWib(windowStart), fromWib(windowEnd), reason))"><h2>Jendela moderasi / revisi final</h2><p class="op-caption">Membuka kesempatan merevisi penilaian yang sudah final setelah periode normal tutup. Tidak membuka penilaian awal atau pengumpulan peserta.</p><label class="op-field">Periode<select v-model="windowPeriod" required><option value="">Pilih periode</option><option v-for="p in data.periods.filter(p => !p.archived)" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><div class="op-grid"><label class="op-field">Dibuka (WIB)<input v-model="windowStart" type="datetime-local" required /></label><label class="op-field">Ditutup (WIB)<input v-model="windowEnd" type="datetime-local" required /></label></div><UButton type="submit" variant="soft">Tetapkan jendela beralasan</UButton></form>
      <form class="op-panel" @submit.prevent="act(() => u.operations.enrollParticipant(enrollment.periodId, enrollment.participantId, enrollment.subject, reason), 'Peserta ditambahkan dengan paket draf kosong pada periode terpilih.')"><h2>Tambahkan peserta fiktif ke periode</h2><p class="op-caption">Membuka paket kosong pada periode lain. Riwayat retaker yang sudah tersedia tetap dipertahankan.</p><div class="op-grid three"><label class="op-field">Periode<select v-model="enrollment.periodId" required><option value="">Pilih</option><option v-for="p in data.periods.filter(p => !p.archived)" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label class="op-field">Peserta<select v-model="enrollment.participantId" required><option value="">Pilih</option><option v-for="p in data.users.filter(u => u.role === 'peserta' && u.active)" :key="p.id" :value="p.id">{{ p.displayName }}</option></select></label><label class="op-field">Bidang studi<select v-model="enrollment.subject" required><option value="">Pilih</option><option v-for="s in data.periods.find(p => p.id === enrollment.periodId)?.subjects ?? []" :key="s">{{ s }}</option></select></label></div><UButton type="submit" variant="soft">Tambahkan peserta</UButton></form>
    </template>
    <template v-if="tab === 'Akun'"><section class="op-panel"><div class="op-row"><h2>{{ data.users.length }} akun fiktif</h2><UButton @click="editUser()">Akun baru</UButton></div><p class="op-caption">Empat akun interaktif bawaan tetap menjadi sarana demonstrasi. Akun tambahan hanya data administrasi dan penugasan.</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Nama</th><th>Peran</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><tr v-for="a in data.users" :key="a.id"><td>{{ a.displayName }}<small>{{ a.email }}</small></td><td>{{ roleLabel(a) }}<small>{{ a.interactive ? 'Akun login demo' : 'Data administrasi' }}</small></td><td>{{ a.active ? 'Aktif' : 'Nonaktif' }}</td><td><UButton size="sm" variant="soft" @click="editUser(a)">Sunting</UButton><UButton v-if="!a.interactive" size="sm" color="error" variant="ghost" @click="act(() => u.operations.deleteManagedUser(a.id, reason))">Hapus jika belum dipakai</UButton></td></tr></tbody></table></div></section><form v-if="account" class="op-panel" @submit.prevent="saveUser"><h2>{{ account.id ? 'Sunting akun' : 'Akun administrasi baru' }}</h2><div class="op-grid"><label class="op-field">Nama fiktif<input v-model="account.displayName" required maxlength="120" /></label><label class="op-field">Email .invalid<input v-model="account.email" type="email" required /></label><label class="op-field">Peran<select v-model="account.role"><option value="peserta">Peserta</option><option value="penguji">Penguji</option><option value="pengelola">Pengelola (data saja)</option></select></label><label v-if="account.role === 'penguji'" class="op-field">Jenis penguji<select v-model="account.examinerKind" required><option value="dosen">Dosen</option><option value="guru">Guru</option></select></label></div><label class="op-check"><input v-model="account.active" type="checkbox" />Akun aktif</label><div class="op-actions"><UButton type="submit">Simpan akun</UButton><UButton color="neutral" variant="outline" @click="account = null">Batal</UButton></div></form></template>
    <template v-if="tab === 'Penugasan'"><section class="op-panel"><h2>Pasangan dosen dan guru</h2><label class="op-field">Paket peserta<select v-model="attemptId"><option value="">Pilih paket</option><option v-for="a in data.attempts.filter(a => !a.archived)" :key="a.id" :value="a.id">{{ data.users.find(u => u.id === a.participantId)?.displayName }} / {{ data.periods.find(p => p.id === a.periodId)?.name }} / v{{ a.evidenceVersion ?? '-' }}</option></select></label><template v-if="assignmentPreview"><p class="op-warning">Penggantian penugasan mengarsipkan kasus terbuka, menarik publikasi, dan membatalkan jadwal terkait. Skor penguji lama tetap di riwayat dan tidak dipindahkan.</p><p class="op-caption">Kelengkapan: {{ assignmentPreview.attempt.completeness }}. {{ assignmentPreview.assignments.filter(a => a.started).length }} penguji sudah memulai pekerjaan.</p><div class="op-grid"><label class="op-field">Penguji dosen<select v-model="dosen"><option value="">Pilih dosen</option><option v-for="a in data.users.filter(a => a.active && a.examinerKind === 'dosen')" :key="a.id" :value="a.id">{{ a.displayName }}{{ a.interactive ? '' : ' (data saja)' }}</option></select></label><label class="op-field">Penguji guru<select v-model="guru"><option value="">Pilih guru</option><option v-for="a in data.users.filter(a => a.active && a.examinerKind === 'guru')" :key="a.id" :value="a.id">{{ a.displayName }}{{ a.interactive ? '' : ' (data saja)' }}</option></select></label></div><label class="op-check"><input v-model="confirmPair" type="checkbox" />Saya sudah memeriksa versi paket, pasangan, dan konsekuensi penggantian.</label><UButton @click="savePair">Tetapkan pasangan</UButton></template></section></template>
    <template v-if="tab === 'Pengumuman'"><section class="op-panel"><div class="op-row"><h2>Pengumuman bertarget</h2><UButton @click="editAnnouncement()">Buat draf</UButton></div><article v-for="a in data.announcements" :key="a.id" class="op-divider"><div class="op-row"><h3>{{ a.title }}</h3><span class="op-tag">{{ a.status ?? 'published' }}</span></div><p class="op-note">{{ a.body }}</p><p class="op-caption">Penerima: {{ a.audience.join(', ') }} / {{ a.periodIds?.map(id => data?.periods.find(p => p.id === id)?.name).join(', ') ?? 'Semua periode (pengumuman bawaan)' }}</p><div class="op-actions"><UButton v-if="a.status === 'draft'" variant="soft" @click="editAnnouncement(a)">Sunting draf</UButton><UButton v-if="a.status === 'draft'" @click="act(() => u.operations.setAnnouncementStatus(a.id, 'published', reason))">Terbitkan</UButton><UButton v-if="a.status !== 'archived'" color="neutral" variant="outline" @click="act(() => u.operations.setAnnouncementStatus(a.id, 'archived', reason))">Arsipkan</UButton></div></article></section><form v-if="announcement" class="op-panel" @submit.prevent="saveAnnouncement"><h2>Draf pengumuman</h2><label class="op-field">Judul<input v-model="announcement.title" required maxlength="180" /></label><label class="op-field">Isi<textarea v-model="announcement.body" required maxlength="5000" /></label><div class="op-grid"><fieldset><legend>Peran penerima</legend><label v-for="r in (['peserta', 'penguji', 'pengelola'] as const)" :key="r" class="op-check"><input v-model="announcement.audience" type="checkbox" :value="r" />{{ r }}</label></fieldset><fieldset><legend>Periode penerima</legend><label v-for="p in data.periods" :key="p.id" class="op-check"><input v-model="announcement.periodIds" type="checkbox" :value="p.id" />{{ p.name }}</label></fieldset></div><div class="op-actions"><UButton type="submit">Simpan draf</UButton><UButton color="neutral" variant="outline" @click="announcement = null">Batal</UButton></div></form></template>
    <section v-if="tab === 'Aktivitas'" class="op-panel"><h2>Jejak administrasi</h2><p class="op-caption">Riwayat lokal simulasi, bukan audit log production. Riwayat pengiriman dan penilaian tetap tersedia pada ruang masing-masing.</p><p v-if="!data.events.length" class="op-empty">Belum ada tindakan administratif Tahap 4.</p><article v-for="e in data.events" :key="e.id" class="op-divider"><strong>{{ e.action }}</strong><p class="op-note">{{ e.reason }}</p><p class="op-caption">{{ data.users.find(u => u.id === e.actorId)?.displayName ?? e.actorId }} / {{ formatDemoTime(e.at) }}</p><small class="op-caption">{{ e.entityId }}</small></article></section>
  </div>
</template>
